phase1.code:
fn main() {
    println!("=== Functions ===");

    // Call a function that returns a value
    let sum = add(5, 3);
    println!("5 + 3 = {}", sum);

    // Call a function with no return value
    greet("Hero");

    // Call a function with multiple return values
    let (x, y) = swap(10, 20);
    println!("Swapped: x={}, y={}", x, y);

    // Call a function that returns an expression
    let area = rectangle_area(10, 5);
    println!("Area: {}", area);

    // Call a function with a function as argument
    let result = apply(5, 3, add);
    println!("apply(add): {}", result);
}

// ---- Function with parameters and return value ----
fn add(a: i32, b: i32) -> i32 {
    a + b  // No semicolon = expression (returned)
}

// ---- Function with no return value (unit type) ----
fn greet(name: &str) {
    println!("Hello, {}!", name);
}

// ---- Function returning a tuple ----
fn swap(a: i32, b: i32) -> (i32, i32) {
    (b, a)
}

// ---- Function using a block expression ----
fn rectangle_area(width: i32, height: i32) -> i32 {
    let area = width * height;
    area  // Return with semicolon (explicit)
}

// ---- Function that takes a function ----
fn apply(a: i32, b: i32, f: fn(i32, i32) -> i32) -> i32 {
    f(a, b)
}

