fn main() {
    println!("Multiply: {}", multiply(10, 5));
    println!("Subtract: {}", subtract(10, 5));
    println!("Add three: {}", add_three(10, 5, 3));
}

fn multiply(a: i32, b: i32) -> i32 {
    a * b
}

fn subtract(a: i32, b: i32) -> i32 {
    a - b
}

fn add_three(a: i32, b: i32, c: i32) -> i32 {
    a + b + c
}
